// Compares MoonWindow's engine with NASA JPL Horizons reference points (tools/horizons_raw.json)
// and writes docs/validation.md. Usage: node tools/compare_horizons.js
// Needs: npm install astronomy-engine@2 (in the project folder).
// Code generated with an AI assistant (Claude) from our team's requirements.
'use strict';
const fs = require('fs');
const path = require('path');
const ROOT = path.resolve(__dirname, '..');
const A = require(path.join(ROOT, 'node_modules', 'astronomy-engine'));
const E = require(path.join(ROOT, 'src', 'engine.js'))(A);

const raw = JSON.parse(fs.readFileSync(path.join(ROOT, 'tools', 'horizons_raw.json'), 'utf8'));
const angDiff = (a, b) => { let d = ((a - b) % 360 + 540) % 360 - 180; return d; };

let maxEl = 0, maxAz = 0, maxAzLow = 0, n = 0;
const rows = raw.results.map(r => {
  const sky = E.skyAt(new Date(r.time), r.lat, r.lon)[r.body];
  const dEl = sky.el - r.el, dAz = angDiff(sky.az, r.az);
  n++;
  maxEl = Math.max(maxEl, Math.abs(dEl));
  maxAz = Math.max(maxAz, Math.abs(dAz));
  if (Math.abs(r.el) < 80) maxAzLow = Math.max(maxAzLow, Math.abs(dAz));
  const sameUp = (sky.el > 0) === (r.el > 0);
  return { ...r, appEl: sky.el, appAz: sky.az, dEl, dAz, sameUp };
});
const flips = rows.filter(r => !r.sameUp).length;
const f = (v, d = 4) => v.toFixed(d);

let md = `# Validation against NASA JPL Horizons\n\n`;
md += `**Result: across ${n} comparisons (${new Set(rows.map(r => r.site)).size} sites, ${raw.times.length} dates, Sun and Earth), `;
md += `the largest elevation difference is ${f(maxEl)}° and the largest azimuth difference is ${f(maxAzLow)}°`;
md += ` (objects below 80° elevation). Up/down status matches in ${n - flips} of ${n} cases.**\n\n`;
md += `Reference: ${raw.source}, fetched ${raw.fetched_utc}. App: \`src/engine.js\` (Astronomy Engine + IAU/WGCCRE 2009 Moon orientation), same sites and times, flat horizon.\n\n`;
if (maxEl < 0.1) md += `Differences this small are far below the Sun's disk width (about 0.53°), so they cannot change whether the Sun or Earth is up except within seconds of a crossing.\n\n`;
md += `| Site | Time (UTC) | Body | Horizons el (°) | App el (°) | Δ el (°) | Horizons az (°) | App az (°) | Δ az (°) |\n|---|---|---|---:|---:|---:|---:|---:|---:|\n`;
for (const r of rows) {
  md += `| ${r.site} | ${r.time.replace('T', ' ').replace(':00Z', '')} | ${r.body} | ${f(r.el, 3)} | ${f(r.appEl, 3)} | ${f(r.dEl)} | ${f(r.az, 3)} | ${f(r.appAz, 3)} | ${f(r.dAz)} |\n`;
}
fs.mkdirSync(path.join(ROOT, 'docs'), { recursive: true });
fs.writeFileSync(path.join(ROOT, 'docs', 'validation.md'), md);
const summary = { comparisons: n, maxElDiffDeg: +maxEl.toFixed(4), maxAzDiffDeg: +maxAzLow.toFixed(4), upDownMatches: n - flips, fetched: raw.fetched_utc };
fs.writeFileSync(path.join(ROOT, 'src', 'validation-data.js'),
  '// Generated by tools/compare_horizons.js from NASA JPL Horizons reference points. Do not edit by hand.\n' +
  'window.MW_VALIDATION = ' + JSON.stringify(summary) + ';\n');
console.log(`Compared ${n} points. Max |Δel| = ${f(maxEl)}°, max |Δaz| (el<80°) = ${f(maxAzLow)}°, up/down mismatches: ${flips}`);
console.log('Wrote docs/validation.md and src/validation-data.js');
process.exit(maxEl < 0.05 ? 0 : 1);
